// 独立实现：奇数位数字乘 7 后反复各位求和至一位数（0 保持 0）
static int transformDigit(int d) {
    if (d == 0) return 0;
    int v = d * 7;
    while (v > 9) {
        int s = 0;
        while (v > 0) { s += v % 10; v /= 10; }
        v = s;
    }
    return v;
}
static string expected(const vector<long long>& xs) {
    ostringstream os;
    for (size_t i = 0; i < xs.size(); ++i) {
        long long t = xs[i];
        int sum = 0, pos = 1;
        if (t == 0) sum = 0;
        while (t > 0) {
            int d = (int)(t % 10);
            if (pos % 2 == 0) sum += d;
            else sum += transformDigit(d);
            t /= 10;
            ++pos;
        }
        os << (sum % 8 == 0 ? "T" : "F");
        if (i + 1 < xs.size()) os << '\n';
    }
    return os.str();
}
static bool check(const string& exe, const vector<long long>& xs, int id) {
    const string inF = "l4a06p1_in.txt", outF = "l4a06p1_out.txt";
    {
        ofstream o(inF);
        o << xs.size() << '\n';
        for (size_t i = 0; i < xs.size(); ++i) o << xs[i] << '\n';
    }
    int code = system(("\"" + exe + "\" < " + inF + " > " + outF + " 2>/dev/null").c_str());
    ifstream in(outF);
    string actual((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    while (!actual.empty() && (actual.back() == '\n' || actual.back() == '\r' || actual.back() == ' '))
        actual.pop_back();
    string want = expected(xs);
    if (code != 0 || actual != want) {
        cout << "[FAIL] case " << id << ": expected=" << want
             << ", actual=" << actual.substr(0, 200) << ", status=" << code << '\n';
        return false;
    }
    return true;
}
int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    const string exe = argv[1];
    vector<vector<long long>> tests;
    tests.push_back({16347, 76344});                                   // 源卷样例
    tests.push_back({5});                                              // 单位数 T
    tests.push_back({8, 1, 2, 3, 4, 6, 7, 9});                        // 单位数 F
    tests.push_back({1000000000000LL});                                // 上界 10^12
    tests.push_back({999999999999LL, 555555555555LL, 111111111111LL}); // 边界形态
    tests.push_back({10, 100, 1000, 10000});
    srand(20230601);
    vector<long long> rnd;
    for (int i = 0; i < 20; ++i) {
        int digits = 1 + rand() % 12;
        long long v = 1;
        for (int k = 0; k < digits - 1; ++k) v = v * 10 + rand() % 10;
        rnd.push_back(v);
